package alloc

const BPS = int64(10_000)

// DefaultBufferBPS keeps 15% of book assets as idle WUGNOT for withdraws.
const DefaultBufferBPS int64 = 1_500

// MinDeploy is 1 GNOT (ugnot units). Smaller leftovers stay idle.
const MinDeploy int64 = 1_000_000

// TargetIdle is the WUGNOT buffer to keep un-deployed.
func TargetIdle(totalAssets, bufferBPS int64) int64 {
	if totalAssets <= 0 || bufferBPS <= 0 {
		return 0
	}
	if bufferBPS >= BPS {
		return totalAssets
	}
	return totalAssets * bufferBPS / BPS
}

// ExcessIdle is capital above the buffer that can go into LP. 0 if too small.
func ExcessIdle(idle, target, minDeploy int64) int64 {
	if idle <= target {
		return 0
	}
	x := idle - target
	if x < minDeploy {
		return 0
	}
	return x
}

// Shortfall is extra WUGNOT needed to pay a withdraw.
func Shortfall(idle, need int64) int64 {
	if need <= idle {
		return 0
	}
	return need - idle
}

package poolkey

import "gno.land/p/nt/ufmt/v0"

// GnoSwap registry keys (pool-path form, no GRC20 seqid).
const (
	WugnotKey = "gno.land/r/gnoland/wugnot.wugnot"
	GnsKey    = "gno.land/r/gnoswap/gns.GNS"
	DefaultFee uint32 = 3000
)

// Spec is one concentrated-liquidity pool the factory can farm.
type Spec struct {
	Path   string
	Token0 string
	Token1 string
	Fee    uint32
	Other  string
}

// DefaultGnsWugnot is the live GNS/WUGNOT 0.30% pool.
func DefaultGnsWugnot() Spec {
	return MustWugnot(PoolPath(WugnotKey, GnsKey, DefaultFee))
}

// PoolPath is the canonical GnoSwap id (lexicographic token0:token1:fee).
func PoolPath(tokenA, tokenB string, fee uint32) string {
	if tokenA == "" || tokenB == "" {
		panic("empty token")
	}
	a, b := tokenA, tokenB
	if a > b {
		a, b = b, a
	}
	return a + ":" + b + ":" + ufmt.Sprintf("%d", fee)
}

// Route is a single-hop swap path: tokenIn:tokenOut:fee.
func Route(tokenIn, tokenOut string, fee uint32) string {
	if tokenIn == "" || tokenOut == "" {
		panic("empty token")
	}
	return tokenIn + ":" + tokenOut + ":" + ufmt.Sprintf("%d", fee)
}

// IsWugnot reports whether key is the wrapped GNOT registry id.
func IsWugnot(key string) bool {
	return key == WugnotKey
}

// Parse splits a GnoSwap pool path. Token paths must not contain ':'.
func Parse(path string) Spec {
	if path == "" {
		panic("empty pool")
	}
	if len(path) > 256 {
		panic("pool path too long")
	}
	feeAt := lastColon(path)
	if feeAt <= 0 || feeAt == len(path)-1 {
		panic("invalid pool path")
	}
	mid := lastColon(path[:feeAt])
	if mid <= 0 {
		panic("invalid pool path")
	}
	token0 := path[:mid]
	token1 := path[mid+1 : feeAt]
	fee := parseFee(path[feeAt+1:])
	if token0 == "" || token1 == "" || token0 == token1 {
		panic("invalid pool tokens")
	}
	if token0 > token1 {
		panic("pool path tokens must be sorted")
	}
	return Spec{Path: path, Token0: token0, Token1: token1, Fee: fee}
}

// MustWugnot parses path and requires exactly one side to be WUGNOT.
func MustWugnot(path string) Spec {
	s := Parse(path)
	w0 := IsWugnot(s.Token0)
	w1 := IsWugnot(s.Token1)
	if w0 == w1 {
		panic("pool must be a WUGNOT pair")
	}
	if w0 {
		s.Other = s.Token1
	} else {
		s.Other = s.Token0
	}
	return s
}

func lastColon(s string) int {
	for i := len(s) - 1; i >= 0; i-- {
		if s[i] == ':' {
			return i
		}
	}
	return -1
}

func parseFee(s string) uint32 {
	if s == "" {
		panic("empty fee")
	}
	var n uint64
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			panic("invalid fee")
		}
		n = n*10 + uint64(c-'0')
		if n > 1_000_000 {
			panic("fee too large")
		}
	}
	if n == 0 {
		panic("fee must be positive")
	}
	return uint32(n)
}

package corev2

import "gno.land/p/nt/avl/v0"

// BPSDenom is 100% in basis points.
const BPSDenom int64 = 10_000

// Book is the share ledger for one vault. Fields stay unexported so foreign
// packages cannot mutate totals or alias the share tree.
type Book struct {
	totalAssets int64
	totalShares int64
	shares      avl.Tree
}

// NewBook returns an empty share ledger.
func NewBook() *Book {
	return &Book{}
}

// TotalAssets is the want-token amount the book currently attributes to depositors.
func (b *Book) TotalAssets() int64 { return b.totalAssets }

// TotalShares is the outstanding share supply.
func (b *Book) TotalShares() int64 { return b.totalShares }

// SharesOf returns the caller's minted shares. Missing accounts are zero.
func (b *Book) SharesOf(addr address) int64 {
	if addr == address("") {
		return 0
	}
	v := b.shares.Get(addr.String())
	if v == nil {
		return 0
	}
	n, ok := v.(int64)
	if !ok {
		panic("corrupt share entry")
	}
	return n
}

// PreviewDeposit is the shares minted for `assets` at the current price.
func (b *Book) PreviewDeposit(assets int64) int64 {
	if assets <= 0 {
		panic("assets must be positive")
	}
	if b.totalShares == 0 || b.totalAssets == 0 {
		return assets
	}
	return mulDiv(assets, b.totalShares, b.totalAssets)
}

// PreviewRedeem is the assets returned for `shares` at the current price.
func (b *Book) PreviewRedeem(shares int64) int64 {
	if shares <= 0 {
		panic("shares must be positive")
	}
	if b.totalShares == 0 {
		panic("no shares")
	}
	if shares == b.totalShares {
		return b.totalAssets
	}
	return mulDiv(shares, b.totalAssets, b.totalShares)
}

// Deposit credits `addr` with newly minted shares against `assets`.
func (b *Book) Deposit(addr address, assets int64) int64 {
	if addr == address("") {
		panic("empty address")
	}
	minted := b.PreviewDeposit(assets)
	if minted <= 0 {
		panic("zero shares")
	}
	nextAssets, ok := add64(b.totalAssets, assets)
	if !ok {
		panic("assets overflow")
	}
	nextShares, ok := add64(b.totalShares, minted)
	if !ok {
		panic("shares overflow")
	}
	held := b.SharesOf(addr)
	nextHeld, ok := add64(held, minted)
	if !ok {
		panic("account shares overflow")
	}
	b.totalAssets = nextAssets
	b.totalShares = nextShares
	b.shares.Set(addr.String(), nextHeld)
	return minted
}

// Withdraw burns `shares` from `addr` and returns the matching asset amount.
func (b *Book) Withdraw(addr address, shares int64) int64 {
	if addr == address("") {
		panic("empty address")
	}
	held := b.SharesOf(addr)
	if shares > held {
		panic("insufficient shares")
	}
	assets := b.PreviewRedeem(shares)
	if assets <= 0 {
		panic("zero assets")
	}
	if assets > b.totalAssets {
		panic("insolvent")
	}
	b.totalAssets -= assets
	b.totalShares -= shares
	remain := held - shares
	if remain == 0 {
		b.shares.Remove(addr.String())
	} else {
		b.shares.Set(addr.String(), remain)
	}
	return assets
}

// AddProfit increases totalAssets without minting shares (harvest / donation).
func (b *Book) AddProfit(assets int64) {
	if assets <= 0 {
		panic("profit must be positive")
	}
	if b.totalShares == 0 {
		panic("no depositors")
	}
	next, ok := add64(b.totalAssets, assets)
	if !ok {
		panic("assets overflow")
	}
	b.totalAssets = next
}

// TakeLoss decreases totalAssets (protocol fee taken from harvest before this
// is not a loss; use this only when the adapter reports a realized drawdown).
func (b *Book) TakeLoss(assets int64) {
	if assets <= 0 {
		panic("loss must be positive")
	}
	if assets > b.totalAssets {
		panic("loss exceeds assets")
	}
	b.totalAssets -= assets
}

func add64(a, b int64) (int64, bool) {
	if a > 0 && b > mathMaxInt64-a {
		return 0, false
	}
	if a < 0 && b < mathMinInt64-a {
		return 0, false
	}
	return a + b, true
}

const (
	mathMaxInt64 = int64(9223372036854775807)
	mathMinInt64 = int64(-9223372036854775808)
)

// mulDiv computes floor(a*b/denom) for non-negative inputs without overflowing
// int64 intermediates. Divides the larger factor first so a partial redeem
// (shares < supply, assets ~ 8e9) does not panic.
func mulDiv(a, b, denom int64) int64 {
	if denom <= 0 {
		panic("division by zero")
	}
	if a < 0 || b < 0 {
		panic("mulDiv expects non-negative")
	}
	if a == 0 || b == 0 {
		return 0
	}
	if a < b {
		a, b = b, a
	}
	if a <= mathMaxInt64/b {
		return a * b / denom
	}
	q := a / denom
	r := a % denom
	out, ok := mul64(q, b)
	if !ok {
		panic("mulDiv overflow")
	}
	var extra int64
	if r == 0 || b == 0 {
		extra = 0
	} else if r <= mathMaxInt64/b {
		extra = r * b / denom
	} else {
		extra = mulDiv(r, b, denom)
	}
	sum, ok := add64(out, extra)
	if !ok {
		panic("mulDiv overflow")
	}
	return sum
}

func mul64(a, b int64) (int64, bool) {
	if a == 0 || b == 0 {
		return 0, true
	}
	if a > mathMaxInt64/b {
		return 0, false
	}
	return a * b, true
}

package corev2

// FeeConfig is the harvest split. Sum of bps must stay below BPSDenom so
// depositors always keep a remainder.
type FeeConfig struct {
	CallerBPS   int64
	ProtocolBPS int64
}

// DefaultFees is 0.5% caller bounty + 5% protocol, matching Yield Yak's
// typical harvest-fee band (no deposit/withdraw fee).
func DefaultFees() FeeConfig {
	return FeeConfig{CallerBPS: 50, ProtocolBPS: 500}
}

// Validate panics if the fee pair is unusable.
func (f FeeConfig) Validate() {
	if f.CallerBPS < 0 || f.ProtocolBPS < 0 {
		panic("negative fee")
	}
	sum, ok := add64(f.CallerBPS, f.ProtocolBPS)
	if !ok || sum >= BPSDenom {
		panic("fees must leave a remainder for depositors")
	}
}

// SplitHarvest divides `profit` into caller bounty, protocol cut, and the
// amount that compounds. Dust from integer division stays with compound.
func SplitHarvest(profit int64, fees FeeConfig) (caller, protocol, compound int64) {
	if profit <= 0 {
		panic("profit must be positive")
	}
	fees.Validate()
	caller = mulDiv(profit, fees.CallerBPS, BPSDenom)
	protocol = mulDiv(profit, fees.ProtocolBPS, BPSDenom)
	used, ok := add64(caller, protocol)
	if !ok || used > profit {
		panic("fee overflow")
	}
	compound = profit - used
	return
}

// ReinvestGuard stops empty or rapid harvests (Yield Yak's min-reward + cooldown).
type ReinvestGuard struct {
	MinProfit    int64
	MinInterval  int64
	LastUnix     int64
	LastHeight   int64
}

// DefaultGuard requires at least 1 unit of profit and a 1-block gap.
func DefaultGuard() ReinvestGuard {
	return ReinvestGuard{MinProfit: 1, MinInterval: 1}
}

// Check panics when this harvest should not run.
func (g ReinvestGuard) Check(profit, nowUnix, height int64) {
	if profit < g.MinProfit {
		panic("profit below minimum")
	}
	if g.MinInterval <= 0 {
		return
	}
	if g.LastHeight != 0 && height <= g.LastHeight {
		panic("reinvest too soon")
	}
	if g.LastUnix != 0 && nowUnix > 0 && nowUnix-g.LastUnix < g.MinInterval {
		panic("reinvest too soon")
	}
}

package gsfarmv8

import (
	"chain"
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gvs/alloc"
	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gvs/corev2"
	"gno.land/p/g1mv0052e7r6s09f5t9xsqf00nj3tqsgt9dg52jr/gvs/poolkey"
	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"
)

// Multi-pool WUGNOT factory. Each GnoSwap WUGNOT pair gets its own share
// book and LP position inside this realm. Opening a missing pool is
// Ensure / first Deposit — not a new MsgAddPackage (Gno cannot addpkg
// from a realm). v6 stays frozen: its Reinvest panics on auto-stake
// because buyGnsForStake swapped stale book cash after mint. v7 spends
// only live WUGNOT above the 15% idle buffer, but re-applies MinDeploy
// after swapping half of excess so a 2 GNOT slot cannot mint. v8 mints
// with that half and does not panic when there is nothing to do.

type slot struct {
	spec           poolkey.Spec
	book           *corev2.Book
	cash           int64
	lpHeld         int64
	positionID     uint64
	staked         bool
	protocolEarned int64
	lastHarvest    int64
	lastDeployed   int64
	guard          corev2.ReinvestGuard
}

type state struct {
	admin         address
	treasury      address
	self          address
	paused        bool
	bufferBPS     int64
	fees          corev2.FeeConfig
	byPool        avl.Tree
	stakeEnabled   bool
	maxAssets      int64
	amountOutMin   string
	minStakeAssets int64
}

var g *state

func init() {
	deployer := unsafe.OriginCaller()
	g = newState(deployer, unsafe.CurrentRealm().Address())
}

func newState(admin, self address) *state {
	return &state{
		admin:     admin,
		treasury:  admin,
		self:      self,
		bufferBPS:     alloc.DefaultBufferBPS,
		fees:          corev2.DefaultFees(),
		amountOutMin:  "0",
		stakeEnabled:  false,
		minStakeAssets: 20_000_000,
	}
}

func IsFactory() bool { return true }
func Admin() address  { return g.admin }
func Treasury() address { return g.treasury }
func VaultAddress() address { return g.self }
func Paused() bool    { return g.paused }
func BufferBPS() int64    { return g.bufferBPS }
func StakeEnabled() bool   { return g.stakeEnabled }
func MinStakeAssets() int64 { return g.minStakeAssets }
func MaxAssets() int64    { return g.maxAssets }
func AmountOutMin() string { return g.amountOutMin }
func Count() int      { return g.byPool.Size() }
func Want() string    { return poolkey.WugnotKey }
func DefaultPool() string { return poolkey.DefaultGnsWugnot().Path }

func PoolPaths() []string {
	out := make([]string, 0, g.byPool.Size())
	g.byPool.Iterate("", "", func(key string, _ any) bool {
		out = append(out, key)
		return false
	})
	return out
}

func Has(poolPath string) bool { return g.byPool.Has(poolPath) }

func TotalAssets() int64 {
	var sum int64
	g.byPool.Iterate("", "", func(_ string, v any) bool {
		sum += v.(*slot).book.TotalAssets()
		return false
	})
	return sum
}

func TotalShares() int64          { return totalSharesOf(DefaultPool()) }
func SharesOf(a address) int64    { return sharesOfPool(DefaultPool(), a) }
func PreviewDeposit(a int64) int64 { return previewDepositOf(DefaultPool(), a) }
func PreviewRedeem(s int64) int64 { return previewRedeemOf(DefaultPool(), s) }
func IdleWugnot() int64           { return idleOf(DefaultPool()) }
func TargetIdleWugnot() int64     { return targetIdleOf(DefaultPool()) }
func PositionID() uint64          { return positionIDOf(DefaultPool()) }
func ProtocolEarned() int64       { return protocolEarnedOf(DefaultPool()) }
func LastHarvest() int64          { return lastHarvestOf(DefaultPool()) }
func SharePriceE6() int64         { return sharePriceOf(DefaultPool()) }
func PendingGns() int64           { return pendingOtherOf(DefaultPool()) }
func CashWugnot() int64           { return idleOf(DefaultPool()) }

func TotalAssetsOf(poolPath string) int64  { return mustGet(poolPath).book.TotalAssets() }
func TotalSharesOf(poolPath string) int64  { return totalSharesOf(poolPath) }
func SharesOfPool(poolPath string, a address) int64 { return sharesOfPool(poolPath, a) }
func PreviewDepositOf(poolPath string, a int64) int64 { return previewDepositOf(poolPath, a) }
func PreviewRedeemOf(poolPath string, s int64) int64 { return previewRedeemOf(poolPath, s) }
func IdleOf(poolPath string) int64         { return idleOf(poolPath) }
func TargetIdleOf(poolPath string) int64   { return targetIdleOf(poolPath) }
func PositionIDOf(poolPath string) uint64  { return positionIDOf(poolPath) }
func ProtocolEarnedOf(poolPath string) int64 { return protocolEarnedOf(poolPath) }
func LastHarvestOf(poolPath string) int64  { return lastHarvestOf(poolPath) }
func SharePriceE6Of(poolPath string) int64 { return sharePriceOf(poolPath) }
func PendingOtherOf(poolPath string) int64 { return pendingOtherOf(poolPath) }

func UserAssets(a address) int64 {
	if a == address("") {
		return 0
	}
	var sum int64
	g.byPool.Iterate("", "", func(_ string, v any) bool {
		f := v.(*slot)
		sh := f.book.SharesOf(a)
		if sh > 0 {
			sum += f.book.PreviewRedeem(sh)
		}
		return false
	})
	return sum
}

// Ensure opens a farm slot for a WUGNOT pair if it is not already open.
// Anyone may call it. First Deposit also opens. This is the factory
// "deploy" — a new isolated book, not a new realm path.
func Ensure(cur realm, poolPath string) string {
	mustLive()
	f := ensureSlot(poolPath)
	return f.spec.Path
}

func Deposit(cur realm, poolPath string, amount int64) int64 {
	mustLive()
	if amount <= 0 {
		panic("amount must be positive")
	}
	f := ensureSlot(poolPath)
	if g.maxAssets > 0 && f.book.TotalAssets()+amount > g.maxAssets {
		panic("pool cap exceeded")
	}
	caller := cur.Previous().Address()
	pullWugnot(cur, caller, amount)
	f.cash += amount
	shares := f.book.Deposit(caller, amount)
	chain.Emit("Deposit",
		"pool", f.spec.Path,
		"user", caller.String(),
		"assets", strconv.FormatInt(amount, 10),
		"shares", strconv.FormatInt(shares, 10),
	)
	return shares
}

func Withdraw(cur realm, poolPath string, shares int64) int64 {
	return withdrawTo(cur, poolPath, shares, cur.Previous().Address())
}

// WithdrawTo burns the caller's shares and pays WUGNOT to dest.
func WithdrawTo(cur realm, poolPath string, shares int64, dest address) int64 {
	if dest == address("") {
		panic("empty dest")
	}
	return withdrawTo(cur, poolPath, shares, dest)
}

func Reinvest(cur realm, poolPath string) int64 {
	mustLive()
	f := mustGet(poolPath)
	now := time.Now().Unix()
	height := runtime.ChainHeight()
	if f.guard.LastHeight != 0 && height <= f.guard.LastHeight {
		panic("reinvest too soon")
	}

	profit := harvestLP(cur, f)
	rest := int64(0)
	if profit > 0 {
		callerAmt, protoAmt, compound := corev2.SplitHarvest(profit, g.fees)
		if compound > 0 {
			f.book.AddProfit(compound)
		}
		if callerAmt > 0 {
			if callerAmt > f.cash {
				callerAmt = f.cash
			}
			f.cash -= callerAmt
			pushWugnot(cur, cur.Previous().Address(), callerAmt)
		}
		if protoAmt > 0 {
			if protoAmt > f.cash {
				protoAmt = f.cash
			}
			f.cash -= protoAmt
			pushWugnot(cur, g.treasury, protoAmt)
			next, ok := addEarned(f.protocolEarned, protoAmt)
			if !ok {
				panic("protocol earned overflow")
			}
			f.protocolEarned = next
		}
		rest = compound
		f.lastHarvest = profit
		chain.Emit("Reinvest",
			"pool", f.spec.Path,
			"caller", cur.Previous().Address().String(),
			"profit", strconv.FormatInt(profit, 10),
			"compound", strconv.FormatInt(compound, 10),
			"protocol", strconv.FormatInt(protoAmt, 10),
		)
	}

	deployed := rebalance(cur, f)
	f.lastDeployed = deployed
	f.guard.LastUnix = now
	f.guard.LastHeight = height
	if profit == 0 && deployed == 0 {
		return 0
	}
	return rest
}

func SetBufferBPS(cur realm, bps int64) {
	mustAdmin(cur)
	if bps < 500 || bps > 5_000 {
		panic("buffer must be 5%-50%")
	}
	g.bufferBPS = bps
}

func TransferAdmin(cur realm, next address) {
	mustAdmin(cur)
	if next == address("") {
		panic("empty admin")
	}
	g.admin = next
}

func SetTreasury(cur realm, next address) {
	mustAdmin(cur)
	if next == address("") {
		panic("empty treasury")
	}
	g.treasury = next
}

func SetFees(cur realm, callerBPS, protocolBPS int64) {
	mustAdmin(cur)
	next := corev2.FeeConfig{CallerBPS: callerBPS, ProtocolBPS: protocolBPS}
	next.Validate()
	g.fees = next
}

func SetPaused(cur realm, next bool) {
	mustAdmin(cur)
	g.paused = next
}

func SetStakeEnabled(cur realm, next bool) {
	mustAdmin(cur)
	g.stakeEnabled = next
}

func SetMaxAssets(cur realm, capAmt int64) {
	mustAdmin(cur)
	if capAmt < 0 {
		panic("cap must be >= 0")
	}
	g.maxAssets = capAmt
}

func SetAmountOutMin(cur realm, minOut string) {
	mustAdmin(cur)
	if minOut == "" {
		minOut = "0"
	}
	g.amountOutMin = minOut
}

func StakedOf(poolPath string) bool {
	v := g.byPool.Get(poolPath)
	if v == nil {
		return false
	}
	return v.(*slot).staked
}

func withdrawTo(cur realm, poolPath string, shares int64, dest address) int64 {
	f := mustGet(poolPath)
	caller := cur.Previous().Address()
	need := f.book.PreviewRedeem(shares)
	if f.cash < need {
		unwindAll(cur, f)
		syncBookToCash(f)
	}
	assets := f.book.Withdraw(caller, shares)
	if assets > f.cash {
		assets = f.cash
	}
	f.cash -= assets
	pushWugnot(cur, dest, assets)
	chain.Emit("Withdraw",
		"pool", f.spec.Path,
		"user", caller.String(),
		"dest", dest.String(),
		"shares", strconv.FormatInt(shares, 10),
		"assets", strconv.FormatInt(assets, 10),
	)
	return assets
}

func ensureSlot(poolPath string) *slot {
	if g.byPool.Has(poolPath) {
		return g.byPool.Get(poolPath).(*slot)
	}
	spec := poolkey.MustWugnot(poolPath)
	assertPoolTokens(spec)
	f := &slot{
		spec:  spec,
		book:  corev2.NewBook(),
		guard: corev2.DefaultGuard(),
	}
	f.guard.MinProfit = 0
	g.byPool.Set(spec.Path, f)
	chain.Emit("VaultOpen", "pool", spec.Path, "other", spec.Other)
	return f
}

